insert into hygieia.workout_templates (id, slug, workout_type, level, intensity, title_el, title_en, duration_min, notes_el, notes_en) values
  ('cc599e58-6ffe-abe4-258d-9be8645f046c'::uuid, 'calisthenics-advanced-high', 'calisthenics', 'advanced', 'high', 'Calisthenics · Προχωρημένο · Υψηλή ένταση', 'Calisthenics · Advanced · High intensity', 45, 'Προχωρημένη δύναμη με το βάρος του σώματος: archer κάμψεις, pistol καθίσματα, L-sit και έλξεις μέχρι το στήθος. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Advanced bodyweight strength: archer push-ups, pistol squats, L-sits and chest-to-bar pull-ups. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('aa622637-e572-0cea-3ee0-afdb8c9e6c84'::uuid, 'calisthenics-advanced-low', 'calisthenics', 'advanced', 'low', 'Calisthenics · Προχωρημένο · Χαμηλή ένταση', 'Calisthenics · Advanced · Low intensity', 35, 'Προχωρημένη δύναμη με το βάρος του σώματος: archer κάμψεις, pistol καθίσματα, L-sit και έλξεις μέχρι το στήθος. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Advanced bodyweight strength: archer push-ups, pistol squats, L-sits and chest-to-bar pull-ups. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('238b4230-b80c-8fe2-5cb6-f6cca65febbb'::uuid, 'calisthenics-advanced-moderate', 'calisthenics', 'advanced', 'moderate', 'Calisthenics · Προχωρημένο · Μέτρια ένταση', 'Calisthenics · Advanced · Moderate intensity', 40, 'Προχωρημένη δύναμη με το βάρος του σώματος: archer κάμψεις, pistol καθίσματα, L-sit και έλξεις μέχρι το στήθος. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Advanced bodyweight strength: archer push-ups, pistol squats, L-sits and chest-to-bar pull-ups. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('3d662e90-c10d-9006-fe62-08cef4a14a19'::uuid, 'calisthenics-beginner-high', 'calisthenics', 'beginner', 'high', 'Calisthenics · Αρχάριο · Υψηλή ένταση', 'Calisthenics · Beginner · High intensity', 30, 'Βασικές ασκήσεις στο μονόζυγο και με το βάρος του σώματος, για όποιον χτίζει την πρώτη του έλξη και κάμψη. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Bar and bodyweight basics for someone building their first pull-up and push-up. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('6b1ba7d2-b201-6e36-17db-ac0aebde2d9a'::uuid, 'calisthenics-beginner-low', 'calisthenics', 'beginner', 'low', 'Calisthenics · Αρχάριο · Χαμηλή ένταση', 'Calisthenics · Beginner · Low intensity', 20, 'Βασικές ασκήσεις στο μονόζυγο και με το βάρος του σώματος, για όποιον χτίζει την πρώτη του έλξη και κάμψη. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Bar and bodyweight basics for someone building their first pull-up and push-up. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('008873c2-03dd-3506-2cd3-d55667380ca3'::uuid, 'calisthenics-beginner-moderate', 'calisthenics', 'beginner', 'moderate', 'Calisthenics · Αρχάριο · Μέτρια ένταση', 'Calisthenics · Beginner · Moderate intensity', 25, 'Βασικές ασκήσεις στο μονόζυγο και με το βάρος του σώματος, για όποιον χτίζει την πρώτη του έλξη και κάμψη. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Bar and bodyweight basics for someone building their first pull-up and push-up. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d9afbba3-82cb-1c3b-c8db-e40d9a936784'::uuid, 'calisthenics-intermediate-high', 'calisthenics', 'intermediate', 'high', 'Calisthenics · Μεσαίο · Υψηλή ένταση', 'Calisthenics · Intermediate · High intensity', 45, 'Πρόγραμμα στο μονόζυγο για όποιον κάνει ήδη μερικές καθαρές έλξεις και βυθίσεις. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bar session for someone who can already do a few strict pull-ups and dips. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('f5253d91-076a-b4a1-7a10-028e8518cbc9'::uuid, 'calisthenics-intermediate-low', 'calisthenics', 'intermediate', 'low', 'Calisthenics · Μεσαίο · Χαμηλή ένταση', 'Calisthenics · Intermediate · Low intensity', 35, 'Πρόγραμμα στο μονόζυγο για όποιον κάνει ήδη μερικές καθαρές έλξεις και βυθίσεις. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bar session for someone who can already do a few strict pull-ups and dips. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('58ecde19-f059-4a4f-1f43-07cdfa0d7758'::uuid, 'calisthenics-intermediate-moderate', 'calisthenics', 'intermediate', 'moderate', 'Calisthenics · Μεσαίο · Μέτρια ένταση', 'Calisthenics · Intermediate · Moderate intensity', 40, 'Πρόγραμμα στο μονόζυγο για όποιον κάνει ήδη μερικές καθαρές έλξεις και βυθίσεις. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bar session for someone who can already do a few strict pull-ups and dips. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('497eb4b8-a47e-15f6-10d0-532e8d71fd36'::uuid, 'cycling-advanced-high', 'cycling', 'advanced', 'high', 'Ποδηλασία · Προχωρημένο · Υψηλή ένταση', 'Cycling · Advanced · High intensity', 75, 'Διαστήματα VO2, σπριντ και δύναμη με χαμηλό ρυθμό πεταλιάς, για έμπειρο ποδηλάτη. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'VO2 intervals, sprints and low-cadence strength for an experienced rider. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('6cf293c9-17e3-cd7e-1d21-0be39127bdb7'::uuid, 'cycling-advanced-low', 'cycling', 'advanced', 'low', 'Ποδηλασία · Προχωρημένο · Χαμηλή ένταση', 'Cycling · Advanced · Low intensity', 60, 'Διαστήματα VO2, σπριντ και δύναμη με χαμηλό ρυθμό πεταλιάς, για έμπειρο ποδηλάτη. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'VO2 intervals, sprints and low-cadence strength for an experienced rider. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('9bb40b2d-22f4-fc30-1138-5f3d9ffa01bd'::uuid, 'cycling-advanced-moderate', 'cycling', 'advanced', 'moderate', 'Ποδηλασία · Προχωρημένο · Μέτρια ένταση', 'Cycling · Advanced · Moderate intensity', 65, 'Διαστήματα VO2, σπριντ και δύναμη με χαμηλό ρυθμό πεταλιάς, για έμπειρο ποδηλάτη. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'VO2 intervals, sprints and low-cadence strength for an experienced rider. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('3fc9de4b-231b-b38b-3b74-d626e9cc4a6d'::uuid, 'cycling-beginner-high', 'cycling', 'beginner', 'high', 'Ποδηλασία · Αρχάριο · Υψηλή ένταση', 'Cycling · Beginner · High intensity', 55, 'Σταθερή διαδρομή με ασκήσεις ρυθμού πεταλιάς, για όποιον ξεκινάει τώρα την οργανωμένη ποδηλασία. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A steady ride with cadence drills for someone new to structured cycling. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('51a7b2f0-7f59-3513-da81-f995f23dfbf4'::uuid, 'cycling-beginner-low', 'cycling', 'beginner', 'low', 'Ποδηλασία · Αρχάριο · Χαμηλή ένταση', 'Cycling · Beginner · Low intensity', 40, 'Σταθερή διαδρομή με ασκήσεις ρυθμού πεταλιάς, για όποιον ξεκινάει τώρα την οργανωμένη ποδηλασία. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A steady ride with cadence drills for someone new to structured cycling. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('a0747d1d-44d1-c050-971c-79722fed3c3a'::uuid, 'cycling-beginner-moderate', 'cycling', 'beginner', 'moderate', 'Ποδηλασία · Αρχάριο · Μέτρια ένταση', 'Cycling · Beginner · Moderate intensity', 45, 'Σταθερή διαδρομή με ασκήσεις ρυθμού πεταλιάς, για όποιον ξεκινάει τώρα την οργανωμένη ποδηλασία. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A steady ride with cadence drills for someone new to structured cycling. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('24936268-98f0-a842-21be-b69b2d8203a5'::uuid, 'cycling-intermediate-high', 'cycling', 'intermediate', 'high', 'Ποδηλασία · Μεσαίο · Υψηλή ένταση', 'Cycling · Intermediate · High intensity', 80, 'Tempo και διαστήματα ανηφόρας, για ποδηλάτη που προπονείται δύο με τρεις φορές την εβδομάδα. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Tempo and climbing intervals for a rider who trains two or three times a week. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('10696eaf-bf8e-9375-d942-f9fa518a391b'::uuid, 'cycling-intermediate-low', 'cycling', 'intermediate', 'low', 'Ποδηλασία · Μεσαίο · Χαμηλή ένταση', 'Cycling · Intermediate · Low intensity', 60, 'Tempo και διαστήματα ανηφόρας, για ποδηλάτη που προπονείται δύο με τρεις φορές την εβδομάδα. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Tempo and climbing intervals for a rider who trains two or three times a week. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('aad03795-067a-de26-97eb-0c9bbf826eae'::uuid, 'cycling-intermediate-moderate', 'cycling', 'intermediate', 'moderate', 'Ποδηλασία · Μεσαίο · Μέτρια ένταση', 'Cycling · Intermediate · Moderate intensity', 70, 'Tempo και διαστήματα ανηφόρας, για ποδηλάτη που προπονείται δύο με τρεις φορές την εβδομάδα. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Tempo and climbing intervals for a rider who trains two or three times a week. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d866a390-0028-9b05-f2af-826dcc89d6bb'::uuid, 'gym-advanced-high', 'gym', 'advanced', 'high', 'Γυμναστήριο · Προχωρημένο · Υψηλή ένταση', 'Gym · Advanced · High intensity', 55, 'Βαρύ πρόγραμμα με μπάρα, για ασκούμενους με σταθερή τεχνική στο κάθισμα, την άρση θανάτου και τις πιέσεις. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A heavy barbell session for lifters with solid technique in the squat, deadlift and press. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('eb739607-23c5-2fe5-20b4-e30431b0cf1f'::uuid, 'gym-advanced-low', 'gym', 'advanced', 'low', 'Γυμναστήριο · Προχωρημένο · Χαμηλή ένταση', 'Gym · Advanced · Low intensity', 45, 'Βαρύ πρόγραμμα με μπάρα, για ασκούμενους με σταθερή τεχνική στο κάθισμα, την άρση θανάτου και τις πιέσεις. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A heavy barbell session for lifters with solid technique in the squat, deadlift and press. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('b5e60a77-127c-b3f1-0fa7-5e79924805e7'::uuid, 'gym-advanced-moderate', 'gym', 'advanced', 'moderate', 'Γυμναστήριο · Προχωρημένο · Μέτρια ένταση', 'Gym · Advanced · Moderate intensity', 50, 'Βαρύ πρόγραμμα με μπάρα, για ασκούμενους με σταθερή τεχνική στο κάθισμα, την άρση θανάτου και τις πιέσεις. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A heavy barbell session for lifters with solid technique in the squat, deadlift and press. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('790b9770-fbc4-ab81-74bf-3e4d7d4fea12'::uuid, 'gym-beginner-high', 'gym', 'beginner', 'high', 'Γυμναστήριο · Αρχάριο · Υψηλή ένταση', 'Gym · Beginner · High intensity', 40, 'Πρόγραμμα ολόκληρου σώματος στα μηχανήματα, για τους πρώτους μήνες σου στο γυμναστήριο. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A machine-based full-body session for your first months in the gym. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('9190bfbb-dfa7-fb32-247c-ee8b7bcb59c8'::uuid, 'gym-beginner-low', 'gym', 'beginner', 'low', 'Γυμναστήριο · Αρχάριο · Χαμηλή ένταση', 'Gym · Beginner · Low intensity', 30, 'Πρόγραμμα ολόκληρου σώματος στα μηχανήματα, για τους πρώτους μήνες σου στο γυμναστήριο. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A machine-based full-body session for your first months in the gym. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('8e9df9ac-9fc2-c6f7-adf5-ec0a691dd3fa'::uuid, 'gym-beginner-moderate', 'gym', 'beginner', 'moderate', 'Γυμναστήριο · Αρχάριο · Μέτρια ένταση', 'Gym · Beginner · Moderate intensity', 35, 'Πρόγραμμα ολόκληρου σώματος στα μηχανήματα, για τους πρώτους μήνες σου στο γυμναστήριο. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A machine-based full-body session for your first months in the gym. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('72a57791-3777-287b-255b-74f4a3da4ab8'::uuid, 'gym-intermediate-high', 'gym', 'intermediate', 'high', 'Γυμναστήριο · Μεσαίο · Υψηλή ένταση', 'Gym · Intermediate · High intensity', 50, 'Πρόγραμμα ολόκληρου σώματος με ελεύθερα βάρη, για όποιον νιώθει άνετα με αλτήρες και μπάρα. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A free-weight full-body session for someone comfortable with dumbbells and the barbell. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('c3bc083e-ba27-e471-0734-5f20a1321133'::uuid, 'gym-intermediate-low', 'gym', 'intermediate', 'low', 'Γυμναστήριο · Μεσαίο · Χαμηλή ένταση', 'Gym · Intermediate · Low intensity', 40, 'Πρόγραμμα ολόκληρου σώματος με ελεύθερα βάρη, για όποιον νιώθει άνετα με αλτήρες και μπάρα. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A free-weight full-body session for someone comfortable with dumbbells and the barbell. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('e491d987-3b50-a17d-29d4-ece04ed98bf0'::uuid, 'gym-intermediate-moderate', 'gym', 'intermediate', 'moderate', 'Γυμναστήριο · Μεσαίο · Μέτρια ένταση', 'Gym · Intermediate · Moderate intensity', 45, 'Πρόγραμμα ολόκληρου σώματος με ελεύθερα βάρη, για όποιον νιώθει άνετα με αλτήρες και μπάρα. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A free-weight full-body session for someone comfortable with dumbbells and the barbell. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d5eb1b10-7506-8f99-b23e-7e75f6dbfb6b'::uuid, 'home-advanced-high', 'home', 'advanced', 'high', 'Σπίτι · Προχωρημένο · Υψηλή ένταση', 'Home · Advanced · High intensity', 55, 'Απαιτητικό πρόγραμμα για το σπίτι με άλματα και ασκήσεις στο ένα πόδι, για έμπειρους ασκούμενους. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A demanding home session with jumps and single-leg work for experienced exercisers. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('4318a723-1005-05d9-d011-ec74c3086f27'::uuid, 'home-advanced-low', 'home', 'advanced', 'low', 'Σπίτι · Προχωρημένο · Χαμηλή ένταση', 'Home · Advanced · Low intensity', 40, 'Απαιτητικό πρόγραμμα για το σπίτι με άλματα και ασκήσεις στο ένα πόδι, για έμπειρους ασκούμενους. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A demanding home session with jumps and single-leg work for experienced exercisers. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('7efac9fe-a5ee-6a70-b22e-9982bdb80670'::uuid, 'home-advanced-moderate', 'home', 'advanced', 'moderate', 'Σπίτι · Προχωρημένο · Μέτρια ένταση', 'Home · Advanced · Moderate intensity', 45, 'Απαιτητικό πρόγραμμα για το σπίτι με άλματα και ασκήσεις στο ένα πόδι, για έμπειρους ασκούμενους. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A demanding home session with jumps and single-leg work for experienced exercisers. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('a2cd8db2-3c41-a682-4040-67bd41f2ac7c'::uuid, 'home-beginner-high', 'home', 'beginner', 'high', 'Σπίτι · Αρχάριο · Υψηλή ένταση', 'Home · Beginner · High intensity', 35, 'Πρόγραμμα με το βάρος του σώματος για το σαλόνι σου, για όποιον ξεκινάει τώρα ή επιστρέφει μετά από μεγάλο διάλειμμα. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bodyweight session for your living room, for anyone starting out or coming back after a long break. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('fa264ce9-e504-30a7-2aaf-c1b1644c4801'::uuid, 'home-beginner-low', 'home', 'beginner', 'low', 'Σπίτι · Αρχάριο · Χαμηλή ένταση', 'Home · Beginner · Low intensity', 25, 'Πρόγραμμα με το βάρος του σώματος για το σαλόνι σου, για όποιον ξεκινάει τώρα ή επιστρέφει μετά από μεγάλο διάλειμμα. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bodyweight session for your living room, for anyone starting out or coming back after a long break. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('b7958809-254a-64e4-0089-f12516a83667'::uuid, 'home-beginner-moderate', 'home', 'beginner', 'moderate', 'Σπίτι · Αρχάριο · Μέτρια ένταση', 'Home · Beginner · Moderate intensity', 30, 'Πρόγραμμα με το βάρος του σώματος για το σαλόνι σου, για όποιον ξεκινάει τώρα ή επιστρέφει μετά από μεγάλο διάλειμμα. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A bodyweight session for your living room, for anyone starting out or coming back after a long break. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('8f4b2d7b-9c46-8e1f-45e5-067dc53e37f8'::uuid, 'home-intermediate-high', 'home', 'intermediate', 'high', 'Σπίτι · Μεσαίο · Υψηλή ένταση', 'Home · Intermediate · High intensity', 55, 'Πρόγραμμα για το σπίτι με κάμψεις, προβολές και ένα ζευγάρι αλτήρες, για όποιον γυμνάζεται ήδη τακτικά. Τέσσερα σετ με σύντομες παύσεις· κράτα δύο επαναλήψεις στο απόθεμα και μείωσε το φορτίο πριν χαλάσει η τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A home session with push-ups, lunges and a pair of dumbbells for someone who already trains regularly. Four sets with short rests; keep two reps in reserve and lower the load before you lower the standard. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('119194f2-55ea-d8e3-a8ce-395e65e5c2c0'::uuid, 'home-intermediate-low', 'home', 'intermediate', 'low', 'Σπίτι · Μεσαίο · Χαμηλή ένταση', 'Home · Intermediate · Low intensity', 40, 'Πρόγραμμα για το σπίτι με κάμψεις, προβολές και ένα ζευγάρι αλτήρες, για όποιον γυμνάζεται ήδη τακτικά. Δύο σετ ανά άσκηση με μεγάλες παύσεις — πρόσθεσε ένα σετ ή μείωσε την παύση όταν σου φαίνεται εύκολο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A home session with push-ups, lunges and a pair of dumbbells for someone who already trains regularly. Two sets per exercise with long rests — add a set or shorten the rest when it feels easy. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('833fe833-44ab-2ada-e523-df4c5c72a33b'::uuid, 'home-intermediate-moderate', 'home', 'intermediate', 'moderate', 'Σπίτι · Μεσαίο · Μέτρια ένταση', 'Home · Intermediate · Moderate intensity', 45, 'Πρόγραμμα για το σπίτι με κάμψεις, προβολές και ένα ζευγάρι αλτήρες, για όποιον γυμνάζεται ήδη τακτικά. Τρία σετ ανά άσκηση με ένα λεπτό παύση — αφαίρεσε ένα σετ ή αύξησε την παύση αν δεν κρατάς καλή τεχνική. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A home session with push-ups, lunges and a pair of dumbbells for someone who already trains regularly. Three sets per exercise with a minute''s rest — drop a set or lengthen the rest if you cannot keep good form. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('ae67e203-05a9-8425-80d4-ab9394f92199'::uuid, 'mobility-advanced-high', 'mobility', 'advanced', 'high', 'Κινητικότητα · Προχωρημένο · Υψηλή ένταση', 'Mobility · Advanced · High intensity', 30, 'Κινητικότητα με φορτίο και σε ακραίο εύρος (Cossack καθίσματα, Jefferson curl, γέφυρα), για έμπειρους ασκούμενους. Δύο γύροι με κρατήματα 50 δευτερολέπτων· φτάσε σε έντονη αλλά ανεκτή διάταση, ποτέ σε πόνο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Loaded and end-range mobility (Cossack squats, Jefferson curls, bridge) for experienced movers. Two rounds of 50-second holds; go to a strong but comfortable stretch, never into pain. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('649a0cda-e889-1933-281e-6b35a96e06ed'::uuid, 'mobility-advanced-low', 'mobility', 'advanced', 'low', 'Κινητικότητα · Προχωρημένο · Χαμηλή ένταση', 'Mobility · Advanced · Low intensity', 20, 'Κινητικότητα με φορτίο και σε ακραίο εύρος (Cossack καθίσματα, Jefferson curl, γέφυρα), για έμπειρους ασκούμενους. Κράτα κάθε θέση περίπου 30 δευτερόλεπτα και ανάπνεε αργά· χωρίς αναπηδήσεις. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Loaded and end-range mobility (Cossack squats, Jefferson curls, bridge) for experienced movers. Hold each position for about 30 seconds and breathe slowly; no bouncing. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('5bbff2e7-82c8-40ee-5083-554efae66251'::uuid, 'mobility-advanced-moderate', 'mobility', 'advanced', 'moderate', 'Κινητικότητα · Προχωρημένο · Μέτρια ένταση', 'Mobility · Advanced · Moderate intensity', 20, 'Κινητικότητα με φορτίο και σε ακραίο εύρος (Cossack καθίσματα, Jefferson curl, γέφυρα), για έμπειρους ασκούμενους. Κράτα κάθε θέση περίπου 40 δευτερόλεπτα, πηγαίνοντας λίγο βαθύτερα σε κάθε εκπνοή. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Loaded and end-range mobility (Cossack squats, Jefferson curls, bridge) for experienced movers. Hold each position for about 40 seconds, moving a little deeper on each exhale. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('77dc5552-7b62-2d80-64c5-8fdbb4830e7f'::uuid, 'mobility-beginner-high', 'mobility', 'beginner', 'high', 'Κινητικότητα · Αρχάριο · Υψηλή ένταση', 'Mobility · Beginner · High intensity', 15, 'Ήπιες κυκλικές κινήσεις των αρθρώσεων και διατάσεις στο στρώμα· ταιριάζει κάθε μέρα, ακόμη και στις μέρες ξεκούρασης. Δύο γύροι με κρατήματα 50 δευτερολέπτων· φτάσε σε έντονη αλλά ανεκτή διάταση, ποτέ σε πόνο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Gentle joint circles and floor stretches; suitable on any day, including rest days. Two rounds of 50-second holds; go to a strong but comfortable stretch, never into pain. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('9337c1b6-9efe-4a4a-59ce-71d13f989b59'::uuid, 'mobility-beginner-low', 'mobility', 'beginner', 'low', 'Κινητικότητα · Αρχάριο · Χαμηλή ένταση', 'Mobility · Beginner · Low intensity', 10, 'Ήπιες κυκλικές κινήσεις των αρθρώσεων και διατάσεις στο στρώμα· ταιριάζει κάθε μέρα, ακόμη και στις μέρες ξεκούρασης. Κράτα κάθε θέση περίπου 30 δευτερόλεπτα και ανάπνεε αργά· χωρίς αναπηδήσεις. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Gentle joint circles and floor stretches; suitable on any day, including rest days. Hold each position for about 30 seconds and breathe slowly; no bouncing. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('3351f957-0db1-56c7-dfc6-dedf3a4c3fbb'::uuid, 'mobility-beginner-moderate', 'mobility', 'beginner', 'moderate', 'Κινητικότητα · Αρχάριο · Μέτρια ένταση', 'Mobility · Beginner · Moderate intensity', 10, 'Ήπιες κυκλικές κινήσεις των αρθρώσεων και διατάσεις στο στρώμα· ταιριάζει κάθε μέρα, ακόμη και στις μέρες ξεκούρασης. Κράτα κάθε θέση περίπου 40 δευτερόλεπτα, πηγαίνοντας λίγο βαθύτερα σε κάθε εκπνοή. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Gentle joint circles and floor stretches; suitable on any day, including rest days. Hold each position for about 40 seconds, moving a little deeper on each exhale. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('9c439bc5-fd1a-127a-04b6-738d20e6663d'::uuid, 'mobility-intermediate-high', 'mobility', 'intermediate', 'high', 'Κινητικότητα · Μεσαίο · Υψηλή ένταση', 'Mobility · Intermediate · High intensity', 25, 'Ροή κινητικότητας για ισχία, σπονδυλική στήλη και ώμους, για όποιον κάνει ήδη τακτικά διατάσεις. Δύο γύροι με κρατήματα 50 δευτερολέπτων· φτάσε σε έντονη αλλά ανεκτή διάταση, ποτέ σε πόνο. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A flow of hip, spine and shoulder mobility for someone who already stretches regularly. Two rounds of 50-second holds; go to a strong but comfortable stretch, never into pain. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('94d99fa8-6596-a15d-86a2-819a5379f1e7'::uuid, 'mobility-intermediate-low', 'mobility', 'intermediate', 'low', 'Κινητικότητα · Μεσαίο · Χαμηλή ένταση', 'Mobility · Intermediate · Low intensity', 15, 'Ροή κινητικότητας για ισχία, σπονδυλική στήλη και ώμους, για όποιον κάνει ήδη τακτικά διατάσεις. Κράτα κάθε θέση περίπου 30 δευτερόλεπτα και ανάπνεε αργά· χωρίς αναπηδήσεις. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A flow of hip, spine and shoulder mobility for someone who already stretches regularly. Hold each position for about 30 seconds and breathe slowly; no bouncing. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('dd8779ef-c5f6-75f8-bcf2-317a630996c1'::uuid, 'mobility-intermediate-moderate', 'mobility', 'intermediate', 'moderate', 'Κινητικότητα · Μεσαίο · Μέτρια ένταση', 'Mobility · Intermediate · Moderate intensity', 15, 'Ροή κινητικότητας για ισχία, σπονδυλική στήλη και ώμους, για όποιον κάνει ήδη τακτικά διατάσεις. Κράτα κάθε θέση περίπου 40 δευτερόλεπτα, πηγαίνοντας λίγο βαθύτερα σε κάθε εκπνοή. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A flow of hip, spine and shoulder mobility for someone who already stretches regularly. Hold each position for about 40 seconds, moving a little deeper on each exhale. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('63bdd6b8-2d55-2dc2-3dd1-5f5404afc47a'::uuid, 'running-advanced-high', 'running', 'advanced', 'high', 'Τρέξιμο · Προχωρημένο · Υψηλή ένταση', 'Running · Advanced · High intensity', 65, 'Διαλειμματικό στον στίβο και σπριντ σε ανηφόρα, για έμπειρο δρομέα με καλή αερόβια βάση. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Track intervals and hill sprints for an experienced runner with a solid aerobic base. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('c05031c6-966f-57dc-f09d-91bfa8c6fa19'::uuid, 'running-advanced-low', 'running', 'advanced', 'low', 'Τρέξιμο · Προχωρημένο · Χαμηλή ένταση', 'Running · Advanced · Low intensity', 50, 'Διαλειμματικό στον στίβο και σπριντ σε ανηφόρα, για έμπειρο δρομέα με καλή αερόβια βάση. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Track intervals and hill sprints for an experienced runner with a solid aerobic base. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d5c0c823-e72e-67e2-2c3e-989595a9ed7e'::uuid, 'running-advanced-moderate', 'running', 'advanced', 'moderate', 'Τρέξιμο · Προχωρημένο · Μέτρια ένταση', 'Running · Advanced · Moderate intensity', 60, 'Διαλειμματικό στον στίβο και σπριντ σε ανηφόρα, για έμπειρο δρομέα με καλή αερόβια βάση. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Track intervals and hill sprints for an experienced runner with a solid aerobic base. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('09120ac0-fa50-ffb7-3489-633d5cfdca1a'::uuid, 'running-beginner-high', 'running', 'beginner', 'high', 'Τρέξιμο · Αρχάριο · Υψηλή ένταση', 'Running · Beginner · High intensity', 40, 'Πρόγραμμα περπάτημα–τζόκινγκ για όποιον ξεκινάει το τρέξιμο· τα διαλείμματα περπατήματος είναι μέρος του σχεδίου. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A walk–jog session for someone starting to run; the walking breaks are part of the plan. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('c781d835-d50d-e0b2-7451-612c6b88486c'::uuid, 'running-beginner-low', 'running', 'beginner', 'low', 'Τρέξιμο · Αρχάριο · Χαμηλή ένταση', 'Running · Beginner · Low intensity', 35, 'Πρόγραμμα περπάτημα–τζόκινγκ για όποιον ξεκινάει το τρέξιμο· τα διαλείμματα περπατήματος είναι μέρος του σχεδίου. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A walk–jog session for someone starting to run; the walking breaks are part of the plan. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d29ce3a3-63da-fdc1-c676-3f58f43d05b0'::uuid, 'running-beginner-moderate', 'running', 'beginner', 'moderate', 'Τρέξιμο · Αρχάριο · Μέτρια ένταση', 'Running · Beginner · Moderate intensity', 35, 'Πρόγραμμα περπάτημα–τζόκινγκ για όποιον ξεκινάει το τρέξιμο· τα διαλείμματα περπατήματος είναι μέρος του σχεδίου. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A walk–jog session for someone starting to run; the walking breaks are part of the plan. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('4e28885b-5426-1335-d82b-79d60e521f9b'::uuid, 'running-intermediate-high', 'running', 'intermediate', 'high', 'Τρέξιμο · Μεσαίο · Υψηλή ένταση', 'Running · Intermediate · High intensity', 60, 'Πρόγραμμα tempo και fartlek για όποιον τρέχει άνετα 30 λεπτά συνεχόμενα. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A tempo and fartlek session for someone who runs comfortably for 30 minutes. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('e290f928-60cb-76bf-fcf6-2bc14721efc2'::uuid, 'running-intermediate-low', 'running', 'intermediate', 'low', 'Τρέξιμο · Μεσαίο · Χαμηλή ένταση', 'Running · Intermediate · Low intensity', 45, 'Πρόγραμμα tempo και fartlek για όποιον τρέχει άνετα 30 λεπτά συνεχόμενα. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A tempo and fartlek session for someone who runs comfortably for 30 minutes. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('7a00f999-750c-6223-b745-5898c9fd6095'::uuid, 'running-intermediate-moderate', 'running', 'intermediate', 'moderate', 'Τρέξιμο · Μεσαίο · Μέτρια ένταση', 'Running · Intermediate · Moderate intensity', 55, 'Πρόγραμμα tempo και fartlek για όποιον τρέχει άνετα 30 λεπτά συνεχόμενα. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A tempo and fartlek session for someone who runs comfortably for 30 minutes. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('dbef75bd-90c0-c661-9cd5-4d337f789591'::uuid, 'swimming-advanced-high', 'swimming', 'advanced', 'high', 'Κολύμβηση · Προχωρημένο · Υψηλή ένταση', 'Swimming · Advanced · High intensity', 65, 'Διαλειμματικό, πεταλούδα και μικτή ατομική, για έμπειρο κολυμβητή με καλή τεχνική και στα τέσσερα στιλ. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Interval, butterfly and medley work for a confident swimmer with good technique in all four strokes. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('f206794b-42c7-f588-8096-ea4d1ce4b2ef'::uuid, 'swimming-advanced-low', 'swimming', 'advanced', 'low', 'Κολύμβηση · Προχωρημένο · Χαμηλή ένταση', 'Swimming · Advanced · Low intensity', 45, 'Διαλειμματικό, πεταλούδα και μικτή ατομική, για έμπειρο κολυμβητή με καλή τεχνική και στα τέσσερα στιλ. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Interval, butterfly and medley work for a confident swimmer with good technique in all four strokes. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('dfe62532-1997-6030-7059-331c2c1a84fd'::uuid, 'swimming-advanced-moderate', 'swimming', 'advanced', 'moderate', 'Κολύμβηση · Προχωρημένο · Μέτρια ένταση', 'Swimming · Advanced · Moderate intensity', 55, 'Διαλειμματικό, πεταλούδα και μικτή ατομική, για έμπειρο κολυμβητή με καλή τεχνική και στα τέσσερα στιλ. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Interval, butterfly and medley work for a confident swimmer with good technique in all four strokes. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('28e10b9f-d63f-138a-68b7-496d3c2390e6'::uuid, 'swimming-beginner-high', 'swimming', 'beginner', 'high', 'Κολύμβηση · Αρχάριο · Υψηλή ένταση', 'Swimming · Beginner · High intensity', 30, 'Σύντομες επαναλήψεις ελεύθερου με σανίδα και εξάσκηση στην αναπνοή, για όποιον ξεκινάει την κολύμβηση. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Short freestyle repeats with a kickboard and breathing practice for a new swimmer. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('696cb588-21f1-100e-15d6-79296b733c1c'::uuid, 'swimming-beginner-low', 'swimming', 'beginner', 'low', 'Κολύμβηση · Αρχάριο · Χαμηλή ένταση', 'Swimming · Beginner · Low intensity', 20, 'Σύντομες επαναλήψεις ελεύθερου με σανίδα και εξάσκηση στην αναπνοή, για όποιον ξεκινάει την κολύμβηση. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Short freestyle repeats with a kickboard and breathing practice for a new swimmer. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('d5bcb1e0-8f91-ba61-40a4-108c16a30199'::uuid, 'swimming-beginner-moderate', 'swimming', 'beginner', 'moderate', 'Κολύμβηση · Αρχάριο · Μέτρια ένταση', 'Swimming · Beginner · Moderate intensity', 25, 'Σύντομες επαναλήψεις ελεύθερου με σανίδα και εξάσκηση στην αναπνοή, για όποιον ξεκινάει την κολύμβηση. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'Short freestyle repeats with a kickboard and breathing practice for a new swimmer. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('643c40d7-ebef-d6df-5357-1740f4ae5efc'::uuid, 'swimming-intermediate-high', 'swimming', 'intermediate', 'high', 'Κολύμβηση · Μεσαίο · Υψηλή ένταση', 'Swimming · Intermediate · High intensity', 60, 'Σετ με διάφορα στιλ, pull buoy και βατραχοπέδιλα, για όποιον κολυμπάει άνετα ένα χιλιόμετρο. Δύσκολο αλλά ελεγχόμενο — σταμάτα το σετ όταν δεν κρατάς πια τον ρυθμό της πρώτης επανάληψης. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A mixed-stroke set with pull buoy and fins for someone who swims a kilometre comfortably. Hard but controlled — stop the set when you can no longer hold the pace of the first repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('74689876-cd0a-0154-83a6-5abd3264d216'::uuid, 'swimming-intermediate-low', 'swimming', 'intermediate', 'low', 'Κολύμβηση · Μεσαίο · Χαμηλή ένταση', 'Swimming · Intermediate · Low intensity', 40, 'Σετ με διάφορα στιλ, pull buoy και βατραχοπέδιλα, για όποιον κολυμπάει άνετα ένα χιλιόμετρο. Κράτα κάθε προσπάθεια σε ρυθμό που μπορείς να μιλάς — αν δεν βγάζεις σύντομες προτάσεις, κόψε ταχύτητα. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A mixed-stroke set with pull buoy and fins for someone who swims a kilometre comfortably. Keep every effort conversational — if you cannot talk in short sentences, slow down. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.'),
  ('28d98901-e77e-3ddd-e073-6f9a942f5db6'::uuid, 'swimming-intermediate-moderate', 'swimming', 'intermediate', 'moderate', 'Κολύμβηση · Μεσαίο · Μέτρια ένταση', 'Swimming · Intermediate · Moderate intensity', 50, 'Σετ με διάφορα στιλ, pull buoy και βατραχοπέδιλα, για όποιον κολυμπάει άνετα ένα χιλιόμετρο. Οι προσπάθειες είναι άνετα δύσκολες· μείωσέ τες ή πρόσθεσε αποκατάσταση αν ο ρυθμός πέφτει στην τελευταία επανάληψη. Σταμάτα αν νιώσεις οξύ πόνο, ζάλη ή ενόχληση στο στήθος, και συμβουλέψου γιατρό πριν ξεκινήσεις αν έχεις κάποιο πρόβλημα υγείας.', 'A mixed-stroke set with pull buoy and fins for someone who swims a kilometre comfortably. Efforts are comfortably hard; shorten them or add recovery if your pace fades in the last repeat. Stop if you feel sharp pain, dizziness or chest discomfort, and talk to a doctor before starting if you have a health condition.')
